// ---------------------------------------------------------------------------
// Registry data layer.
// The whole catalog (1524 components, 68 categories) lives in data/components.json,
// crawled from https://www.relume.ai/react/components. This module is the single
// source of truth for the gallery, the per-component spec pages, and status tracking.
// ---------------------------------------------------------------------------
import manifest from '../../data/components.json';

/** @typedef {typeof manifest.components[number]} Component */

/** Deterministic, URL-safe slug for a catalog entry (unique across the catalog). */
export function slug(c) {
  const base = `${c.category}/${c.name}`.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return base;
}

/** All catalog entries (id order = Relume's catalog order). */
export function all() {
  return manifest.components;
}

/** Unique categories with counts, in catalog order. */
export function categories() {
  const map = new Map();
  for (const c of manifest.components) {
    const e = map.get(c.category) || { name: c.category, count: 0 };
    e.count += 1;
    map.set(c.category, e);
  }
  return [...map.values()];
}

